import importlib, weather; importlib.reload(weather)

def run(fail_n, code=503):
    state={'n':0}
    class H(http.server.BaseHTTPRequestHandler):
        def do_GET(self):
            state['n']+=1
            if state['n']<=fail_n:
                self.send_response(code); self.end_headers(); return
            b=b'{"temp": 20}'; self.send_response(200); self.send_header('Content-Length',str(len(b))); self.end_headers(); self.wfile.write(b)
        def log_message(self,*a): pass
    s=http.server.HTTPServer(('127.0.0.1',0),H); threading.Thread(target=s.serve_forever,daemon=True).start()
    c=weather.WeatherClient(f'http://127.0.0.1:{s.server_port}', backoff=0.05)
    t=time.time()
    try: r=c.get('Oslo')
    except urllib.error.HTTPError as e: r=f'HTTPError {e.code}'
    s.shutdown()
    return r, state['n'], round(time.time()-t,2)

